"use client";

import { useState, useEffect } from "react";
import { useSubmit } from "@/lib/api";
import { Button } from "@/components/finance";
import { TRANSACTION_CATEGORIES, ACCOUNT_TYPES, INSURANCE_TYPES } from "@/components/finance/types";

const AccountForm = ({ onSaved }) => {
  const submit = useSubmit("/api/finance/accounts");
  const [name, setName] = useState("");
  const [type, setType] = useState(ACCOUNT_TYPES[0]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    await submit({ name, type });
    onSaved();
  };

  return (
    <form onSubmit={handleSubmit}>
      <input type="text" value={name} onChange={(e) => setName(e.target.value)} />
      <select value={type} onChange={(e) => setType(e.target.value)}>
        {ACCOUNT_TYPES.map((t) => (
          <option key={t} value={t}>
            {t}
          </option>
        ))}
      </select>
      <Button type="submit">Save</Button>
    </form>
  );
};

